.admin_activation_notice {
	box-sizing: border-box;
	margin-bottom: 15px;
	padding: 6px 12px;
	border: 1px solid rgba(164, 142, 216, 0.82);
	border-radius: 3px;
	background: linear-gradient(90deg, rgba(88, 67, 137, 0.82), rgba(77, 87, 148, 0.82));
