	line-height: 1.4;
	text-align: center;
	overflow-wrap: anywhere;
}

.admin_activation_notice a:link,
.admin_activation_notice a:visited {
	color: #ded3ff;
	font-weight: 700;
	text-decoration: underline;
}

.admin_activation_notice a:hover,
.admin_activation_notice a:active { color: #fff; }

.account_activation_notice {
	display: none;
	align-items: center;
	justify-content: center;
	gap: 8px;
	box-sizing: border-box;
	margin-bottom: 15px;
	padding: 10px 20px;
	border: 1px solid #9a7dce;
	border-radius: 4px;
	background: linear-gradient(90deg, #d4c7f6, #c3c9f5);
	color: #21182f;
	font-size: 12px;
	line-height: 1.5;
	text-align: center;
	overflow-wrap: anywhere;
}

.account_activation_notice.account_activation_group_5 { display: flex; }

.account_activation_notice i { color: #60408f; }

.account_activation_notice a:link,
.account_activation_notice a:visited {
	color: #4b2f7b;
	font-weight: 700;
	text-decoration: underline;
}

.account_activation_notice a:hover,
.account_activation_notice a:active { color: #24103f; }

.usercp_nav_item {
	display: block;
	padding: 1px 0 1px 23px;
	background-image: url(images/usercp_sprite.png);
	background-repeat: no-repeat;
}

.usercp_nav_composepm {
	background-position: 0 0;
}

.usercp_nav_pmfolder {
	background-position: 0 -20px;
}

.usercp_nav_sub_pmfolder {
	padding-left: 40px;
	background-position: 0 -40px;
}

.usercp_nav_trash_pmfolder {
	padding-left: 40px;
	background-position: 0 -60px;
}

.usercp_nav_pmtracking {
	background-position: 0 -80px;
}

.usercp_nav_pmfolders {
	background-position: 0 -100px;
}

.usercp_nav_profile {
	background-position: 0 -120px;
}

.usercp_nav_email {
	padding-left: 40px;
	background-position: 0 -140px;
}

.usercp_nav_password {
	padding-left: 40px;
	background-position: 0 -160px;
}

.usercp_nav_username {
	padding-left: 40px;
	background-position: 0 -180px;
}

.usercp_nav_editsig {
	padding-left: 40px;
	background-position: 0 -200px;
}

.usercp_nav_avatar {
	padding-left: 40px;
	background-position: 0 -220px;
}

.usercp_nav_options {
	background-position: 0 -240px;
}

.usercp_nav_usergroups {
	background-position: 0 -260px;
}

.usercp_nav_editlists {
	background-position: 0 -280px;
}

.usercp_nav_attachments {
	background-position: 0 -300px;
}

.usercp_nav_drafts {
	background-position: 0 -320px;
}

.usercp_nav_subscriptions {
	background-position: 0 -340px;
}

.usercp_nav_fsubscriptions {
	background-position: 0 -360px;
}

.usercp_nav_viewprofile {
	background-position: 0 -380px;
}

.usercp_nav_home {
	background-position: 0 -400px;
}

.usercp_notepad {
	width: 99%;
}

.usercp_container {
	margin: 5px;
	padding: 8px;
	border:1px solid #CCCCCC;
}

.pmspace {
	float: right;
	margin: -3px 5px;
}

.pmspace_container {
	background: #fff;
	border: 1px solid #ccc;
	width: 100px;
	display: inline-block;
}

.pmspace_used {
	display: inline-block;
	color: #fff;
	margin: -1px;
}

.pmspace_used.low {
	border: 1px solid #0c5a01;
	background: #167203;
}

.pmspace_used.medium {
	background: #ff862b;
	border: 1px solid #d7611e;
}

.pmspace_used.high {
	background: #e73c3c;
	border: 1px solid #c00;
}

.pmspace_unused {
	display: inline-block;
}

.pmspace_text {
	padding: 1px 5px;
	display: inline-block;
}

/* Keep User CP and Private Messages panels visually continuous instead of zebra-striped. */
.tborder .trow1,
.tborder .trow2 {
	background: #181818;
	border-left-color: transparent;
	border-right-color: transparent;
}

.new_pm {
	font-weight: bold;
}

templates.template:
{$ignore_bit}{$deleted_bit}
<a name="pid{$post['pid']}" id="pid{$post['pid']}"></a>
<div class="post classic {$unapproved_shade}" style="{$post_visibility}" id="post_{$post['pid']}">
<div class="post_author scaleimages">
	{$post['useravatar']}
	<div class="author_information">
			<strong><span class="largetext">{$post['profilelink']}</span></strong> {$post['onlinestatus']}<br />
			<span class="smalltext">
				{$post['usertitle']}<br />
				{$post['userstars']}
				{$post['groupimage']}
			</span>
	</div>
	<div class="author_statistics">
		{$post['user_details']}
		{$post['iplogged']}
	</div>
</div>
<div class="post_content">
	<div class="post_head">
		{$post['posturl']}
		{$post['icon']}
		<span class="post_date"><i class="fa-regular fa-clock fa-fw" aria-hidden="true"></i> {$post['postdate']} <span class="post_edit" id="edited_by_{$post['pid']}">{$post['editedmsg']}</span></span>
		{$post['subject_extra']}
	</div>
	<div class="soft_deleted_notice"><i class="fa-solid fa-trash-can" aria-hidden="true"></i> This post has been soft deleted.</div>
	<div class="unapproved_post_notice"><i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> This post is awaiting moderation approval.</div>
	<div class="post_body scaleimages" id="pid_{$post['pid']}">
		{$post['message']}
	</div>
	{$post['attachments']}
	{$post['signature']}
	<div class="post_meta" id="post_meta_{$post['pid']}">
		<div class="float_right">
			{$post['poststatus']}
		</div>
	</div>
	{$post['input_editreason']}
</div>
<div class="post_controls">
	<div class="postbit_buttons author_buttons float_left">
		{$post['button_pm']}{$post['button_find']}{$post['button_rep']}
	</div>
	<div class="postbit_buttons post_management_buttons float_right">
		{$post['button_edit']}{$post['button_quickdelete']}{$post['button_quickrestore']}{$post['button_quote']}{$post['button_multiquote']}{$post['button_report']}{$post['button_warn']}{$post['button_purgespammer']}{$post['button_reply_pm']}{$post['button_replyall_pm']}{$post['button_forward_pm']}{$post['button_delete_pm']}
	</div>
</div>
</div>

